INSERT INTO _casino_wave_a_profiles_0087 (case_id, canonical_profile) VALUES ('decentral-games-poker-arcade', '{"schema":"chaindump-entity-profile","version":1,"identity":{"id":"web3_casino:decentral-games-poker-arcade","type":"web3_casino","slug":"decentral-games-poker-arcade","name":"Decentral Games Poker Arcade","aliases":["Poker Arcade","ICE Poker Arcade"]},"classification":{"subtype":"prize poker arcade","tags":["poker","browser_game","prize_arcade","peer_to_peer"],"chains":["Polygon"],"jurisdictions":[]},"status":{"operating_state":"operator_documented_operating","as_of":"2026-08-03","claim_ids":["claim:decentral-games-poker-arcade:status"]},"outcome":{"label":"operating_unclassified","as_of":"2026-08-03","rule_id":"casino-lifecycle-evidence-v1","confidence":"medium","claim_ids":["claim:decentral-games-poker-arcade:outcome"]},"analysis":{"sections":{"what_it_is":{"body":"Poker Arcade is Decentral Games’ browser-based poker product. It offers free-play tables and six-player Sit-and-Go tournaments in which players spend non-transferable Tickets and can earn non-transferable Tournament Badges for prizes. BAG Limited, LTD is the counterparty named in the product terms. The product uses Polygon contracts for Tickets, wearables and related assets, but the reviewed evidence does not show that every card, shuffle or game decision is executed onchain.","as_of":"2026-08-03","claim_ids":["claim:decentral-games-poker-arcade:section:what_it_is:1","claim:decentral-games-poker-arcade:section:what_it_is:2"]},"what_happened":{"body":"Decentral Games launched ICE Poker in October 2021 and later added a separate web and mobile Arcade product. An independent study found that historical ICE Poker casinos accounted for a median 33% of daily distinct Decentraland visitors and 20% of time spent during its measurement window, showing that poker once drove meaningful platform attention. The incentive model also faced inflation pressure as players sold earned ICE. On April 29, 2024, the operator retired the ICE Poker name and moved the product to Poker Arcade, replacing token-earning emphasis with free play, Tickets, Badges and physical or USDT prizes.","as_of":"2026-08-03","claim_ids":["claim:decentral-games-poker-arcade:section:what_happened:1","claim:decentral-games-poker-arcade:section:what_happened:2"]},"why_this_outcome":{"body":"Poker gave Decentral Games a repeat social activity rather than a one-time NFT sale, and wearables supplied identity, access and rewards. That combination helped the old ICE Poker product capture attention inside Decentraland. The same design also tied demand to token incentives, wearable economics and concurrent player density. Poker Arcade’s pivot removes direct play-to-earn claims and lowers the barrier with free play, but it still needs enough simultaneous players to fill tables and enough prize value to make purchased Tickets attractive. Current evidence does not show whether that loop is self-sustaining.","as_of":"2026-08-03","claim_ids":["claim:decentral-games-poker-arcade:section:why_this_outcome:1","claim:decentral-games-poker-arcade:section:why_this_outcome:2"]},"strategic_choices":{"body":"The team chose a narrow poker arcade instead of presenting the product as a general online casino. It shifted from ICE play-to-earn toward non-transferable Tickets and Badges, which can reduce token speculation but makes prize funding and retention harder to observe. It also moved play into a normal browser rather than requiring a visit to Decentraland, widening distribution while weakening the original metaverse moat. Finally, it kept Polygon-linked wearables and rewards, preserving asset continuity without proving that blockchain execution improves the poker game itself.","as_of":"2026-08-03","claim_ids":["claim:decentral-games-poker-arcade:section:strategic_choices:1","claim:decentral-games-poker-arcade:section:strategic_choices:2"]},"operating_model":{"body":"Players can enter free tables or buy Ticket packs with USDT on Polygon and spend Tickets to enter six-player Sit-and-Go tournaments. First- and second-place players receive Badges under the published payout schedule, and Badges can be redeemed in a prize shop. Premium wearable holders can also earn Tickets. BAG Limited controls the customer-facing rules, prize catalogue and service layer; smart contracts and player-held NFTs do not remove that operating role. Poker liquidity is social: a table cannot start until enough players arrive, so concurrent demand matters more than a contract-deployment count.","as_of":"2026-08-03","claim_ids":["claim:decentral-games-poker-arcade:section:operating_model:1","claim:decentral-games-poker-arcade:section:operating_model:2"]},"token_and_value_capture":{"body":"Poker Arcade’s core product units are Tickets and Tournament Badges; both are documented as not transferable. Tickets can be bought with USDT, earned through free play or supplied to wearable holders, while Badges redeem for prizes. Decentral Games migrated the older DG, xDG and ICE tokens to BAG, but BAG is a separate parent-ecosystem token. That history should not be presented as a Poker Arcade wagering token, revenue share or automatic claim on ticket sales. The reviewed sources do not publish ticket revenue, prize expense, rake, a BAG fee right or audited economics.","as_of":"2026-08-03","claim_ids":["claim:decentral-games-poker-arcade:section:token_and_value_capture:1","claim:decentral-games-poker-arcade:section:token_and_value_capture:2"]},"counterfactual":{"body":"Keeping ICE rewards at the center might have preserved a stronger crypto-native hook, but the historical record shows that sell pressure and inflation were already operating constraints. A purely free poker product could remove purchase and prize regulation questions, but would lose direct monetization and high-value rewards. A custodial cash-poker room could simplify onboarding and create clearer rake economics, while adding custody, licensing and withdrawal risk. The most credible improvement is not a theoretical token change: it is publishing current tables, repeat players, ticket sales and prize fulfillment so the product can be judged on real use.","as_of":"2026-08-03","claim_ids":["claim:decentral-games-poker-arcade:section:counterfactual:1","claim:decentral-games-poker-arcade:section:counterfactual:2"]},"risks_and_unknowns":{"body":"The largest commercial unknown is player density: the reviewed sources do not disclose concurrent players, filled tables, hands, repeat play or Ticket conversion. Prize obligations, redemption times and product-level revenue are also unpublished. The terms identify BAG Limited and Polygon, but no gaming licence was verified for this exact product. “Available worldwide” is an operator claim, not legal proof for every player. Contract and NFT ownership do not prove fair shuffle execution, service availability, prize solvency or protection from interface changes. BAG liquidity and price are separate from the arcade’s operating health.","as_of":"2026-08-03","claim_ids":["claim:decentral-games-poker-arcade:section:risks_and_unknowns:1","claim:decentral-games-poker-arcade:section:risks_and_unknowns:2"]},"lifecycle":{"body":"ICE Poker launched in October 2021 as a play-to-earn metaverse game, and a web/mobile Arcade variant followed in September 2022. Independent research found strong historical Decentraland attention alongside declining visits and token-inflation pressure during the measured period. On April 29, 2024, ICE Poker became Poker Arcade and Challenge Mode was phased out. Current documentation presents free play and prize tournaments as the surviving product. The case is therefore an active, heavily pivoted successor, not a clean continuation of the 2021 token economy and not yet a proven commercial success.","as_of":"2026-08-03","claim_ids":["claim:decentral-games-poker-arcade:section:lifecycle:1","claim:decentral-games-poker-arcade:section:lifecycle:2"]},"outlook_and_watch":{"body":"The base case is continued operation as a niche browser prize arcade, supported by free onboarding and the broader Decentral Games rewards system. The upside requires rising filled tables, repeat play and Ticket purchases without unsustainable prize subsidies. The downside is a thin-player spiral in which slower table formation reduces retention, or a legal, prize-funding or product-maintenance problem. Watch concurrent players, tournament starts, hands, 30- and 90-day repeat rates, Ticket purchases, Badge redemptions, prize delivery, wearable-generated Tickets, Poker Arcade releases and any product-specific licence or restriction update.","as_of":"2026-08-03","claim_ids":["claim:decentral-games-poker-arcade:section:outlook_and_watch:1","claim:decentral-games-poker-arcade:section:outlook_and_watch:2"]}}},"metrics":[],"events":[{"id":"event:decentral-games-poker-arcade:ice-launch","type":"launch","date":"2021-10-01","description":"ICE Poker launched during October 2021; the source provides month precision.","claim_ids":["claim:decentral-games-poker-arcade:event:ice-launch"],"date_precision":"month"},{"id":"event:decentral-games-poker-arcade:arcade-launch","type":"product_update","date":"2022-09-01","description":"The separate web and mobile ICE Poker Arcade launched during September 2022; the source provides month precision.","claim_ids":["claim:decentral-games-poker-arcade:event:arcade-launch"],"date_precision":"month"},{"id":"event:decentral-games-poker-arcade:poker-arcade-transition","type":"migration","date":"2024-04-29","description":"ICE Poker became Poker Arcade and Challenge Mode was phased out.","claim_ids":["claim:decentral-games-poker-arcade:event:poker-arcade-transition"],"date_precision":"day"}],"sources":[{"id":"source:decentral-games-poker-arcade:product","title":"Poker Arcade","url":"https://docs.decentral.games/games/poker-arcade","publisher":"Decentral Games","published_at":null,"accessed_at":"2026-08-03T19:31:32Z","archive_url":null,"tier":"B","role":"primary","access_state":"reachable","checked_at":"2026-08-03T19:31:32Z","content_hash":null,"evidence_locator":"Current product overview describes browser play, Free Play, Arcade Mode, levels and prizes.","resolving":true},{"id":"source:decentral-games-poker-arcade:arcade-mode","title":"Arcade Mode","url":"https://docs.decentral.games/games/poker-arcade/arcade-mode","publisher":"Decentral Games","published_at":null,"accessed_at":"2026-08-03T19:31:32Z","archive_url":null,"tier":"B","role":"primary","access_state":"reachable","checked_at":"2026-08-03T19:31:32Z","content_hash":null,"evidence_locator":"Arcade Mode page documents six-player SNGs, USDT ticket packs, badges and prize redemption.","resolving":true},{"id":"source:decentral-games-poker-arcade:terms","title":"Poker Arcade Terms of Use","url":"https://docs.decentral.games/legal/terms-of-use","publisher":"BAG Limited, LTD","published_at":"2024-06-30","accessed_at":"2026-08-03T19:31:32Z","archive_url":null,"tier":"A","role":"primary","access_state":"reachable","checked_at":"2026-08-03T19:31:32Z","content_hash":null,"evidence_locator":"Terms identify BAG Limited, the Poker Arcade product, Polygon contracts, Tickets, Badges and governing-law scope.","resolving":true},{"id":"source:decentral-games-poker-arcade:ice-transition","title":"ICE Poker","url":"https://ice.decentral.games/","publisher":"Decentral Games","published_at":"2024-04-29","accessed_at":"2026-08-03T19:31:32Z","archive_url":null,"tier":"B","role":"primary","access_state":"reachable","checked_at":"2026-08-03T19:31:32Z","content_hash":null,"evidence_locator":"Official transition notice says ICE Poker became Poker Arcade on 2024-04-29.","resolving":true},{"id":"source:decentral-games-poker-arcade:dg-token","title":"DG (Old)","url":"https://docs.decentral.games/tokens/dg-old","publisher":"Decentral Games","published_at":null,"accessed_at":"2026-08-03T19:31:32Z","archive_url":null,"tier":"B","role":"primary","access_state":"reachable","checked_at":"2026-08-03T19:31:32Z","content_hash":null,"evidence_locator":"Token documentation says DG, xDG and ICE migrate to BAG.","resolving":true},{"id":"source:decentral-games-poker-arcade:wearables","title":"Wearable Rewards","url":"https://docs.decentral.games/wearables/wearable-rewards","publisher":"Decentral Games","published_at":null,"accessed_at":"2026-08-03T19:31:32Z","archive_url":null,"tier":"B","role":"primary","access_state":"reachable","checked_at":"2026-08-03T19:31:32Z","content_hash":null,"evidence_locator":"Current rewards page distinguishes Poker Arcade Tickets from Bag.win cash-poker pot bonuses.","resolving":true},{"id":"source:decentral-games-poker-arcade:disclaimer","title":"Notice and Disclaimer","url":"https://docs.decentral.games/legal/disclaimer","publisher":"Decentral Games","published_at":null,"accessed_at":"2026-08-03T19:31:32Z","archive_url":null,"tier":"A","role":"primary","access_state":"reachable","checked_at":"2026-08-03T19:31:32Z","content_hash":null,"evidence_locator":"Disclaimer limits regulatory and BAG-value claims and describes service interruption risk.","resolving":true},{"id":"source:decentral-games-poker-arcade:study","title":"Dressed to Gamble: How Poker Drives the Dynamics of Wearables and Visits on Decentraland","url":"https://arxiv.org/abs/2407.15625","publisher":"Trujillo, Bacciu and Abrate","published_at":"2024-07-22","accessed_at":"2026-08-03T19:31:32Z","archive_url":null,"tier":"A","role":"independent","access_state":"reachable","checked_at":"2026-08-03T19:31:32Z","content_hash":null,"evidence_locator":"Independent study measures historical ICE Poker visits and wearable transfers and documents the Arcade pivot.","resolving":true}],"claims":[{"id":"claim:decentral-games-poker-arcade:status","field_path":"status.operating_state","assertion":"Decentral Games Poker Arcade was operator documented operating at the review date.","value":"operator_documented_operating","as_of":"2026-08-03","confidence":"medium","kind":"fact","source_ids":["source:decentral-games-poker-arcade:product","source:decentral-games-poker-arcade:arcade-mode"],"evidence_locator":"Current documentation links to play and describes live game modes; direct table activity and concurrent players were not independently measured.","support_direction":"supports","note":"Operator-documented status; direct playability and current player density remain unverified.","review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:decentral-games-poker-arcade:outcome","field_path":"outcome.label","assertion":"Decentral Games Poker Arcade is classified operating unclassified as of 2026-08-03.","value":"operating_unclassified","as_of":"2026-08-03","confidence":"medium","kind":"inference","source_ids":["source:decentral-games-poker-arcade:product","source:decentral-games-poker-arcade:ice-transition","source:decentral-games-poker-arcade:study"],"evidence_locator":"A documented live successor and important historical usage, without current tables, retention, prize cost or revenue data.","support_direction":"supports","note":"Lifecycle classification, not a claim of profitability, solvency, legality in every market, or one exclusive cause.","review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:decentral-games-poker-arcade:section:what_it_is:1","field_path":"analysis.sections.what_it_is.body","assertion":"Poker Arcade offers free play and six-player prize tournaments using Tickets and Badges.","value":"Poker Arcade offers free play and six-player prize tournaments using Tickets and Badges.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:decentral-games-poker-arcade:product","source:decentral-games-poker-arcade:arcade-mode"],"evidence_locator":"Current product and Arcade Mode descriptions.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:decentral-games-poker-arcade:section:what_it_is:2","field_path":"analysis.sections.what_it_is.body","assertion":"BAG Limited is the named terms counterparty and Polygon is the documented chain surface.","value":"BAG Limited is the named terms counterparty and Polygon is the documented chain surface.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:decentral-games-poker-arcade:terms"],"evidence_locator":"Operator identity and chain clauses in the 2024 terms.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:decentral-games-poker-arcade:section:what_happened:1","field_path":"analysis.sections.what_happened.body","assertion":"ICE Poker produced disproportionate historical Decentraland visits but the study does not measure current Poker Arcade.","value":"ICE Poker produced disproportionate historical Decentraland visits but the study does not measure current Poker Arcade.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:decentral-games-poker-arcade:study"],"evidence_locator":"Independent historical visit and wearable study.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:decentral-games-poker-arcade:section:what_happened:2","field_path":"analysis.sections.what_happened.body","assertion":"The operator transitioned ICE Poker to Poker Arcade on 2024-04-29.","value":"The operator transitioned ICE Poker to Poker Arcade on 2024-04-29.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:decentral-games-poker-arcade:ice-transition"],"evidence_locator":"Dated official transition notice.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:decentral-games-poker-arcade:section:why_this_outcome:1","field_path":"analysis.sections.why_this_outcome.body","assertion":"Historical poker demand and wearable incentives reinforced one another inside Decentraland.","value":"Historical poker demand and wearable incentives reinforced one another inside Decentraland.","as_of":"2026-08-03","confidence":"medium","kind":"inference","source_ids":["source:decentral-games-poker-arcade:study"],"evidence_locator":"Independent measurement and discussion of visits, wearables and rewards.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:decentral-games-poker-arcade:section:why_this_outcome:2","field_path":"analysis.sections.why_this_outcome.body","assertion":"Current commercial durability is unknown because player density, ticket sales and prize cost are not published.","value":"Current commercial durability is unknown because player density, ticket sales and prize cost are not published.","as_of":"2026-08-03","confidence":"high","kind":"unknown","source_ids":["source:decentral-games-poker-arcade:product","source:decentral-games-poker-arcade:arcade-mode"],"evidence_locator":"Current mechanics disclose rules but not operating results.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:decentral-games-poker-arcade:section:strategic_choices:1","field_path":"analysis.sections.strategic_choices.body","assertion":"The April 2024 pivot replaced the ICE Poker identity with Poker Arcade and browser distribution.","value":"The April 2024 pivot replaced the ICE Poker identity with Poker Arcade and browser distribution.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:decentral-games-poker-arcade:ice-transition","source:decentral-games-poker-arcade:product","source:decentral-games-poker-arcade:study"],"evidence_locator":"Transition notice, current product page and independent lifecycle history.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:decentral-games-poker-arcade:section:strategic_choices:2","field_path":"analysis.sections.strategic_choices.body","assertion":"Tickets and Badges are deliberately non-transferable product units rather than open market tokens.","value":"Tickets and Badges are deliberately non-transferable product units rather than open market tokens.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:decentral-games-poker-arcade:terms","source:decentral-games-poker-arcade:arcade-mode"],"evidence_locator":"Terms and Arcade Mode mechanics.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:decentral-games-poker-arcade:section:operating_model:1","field_path":"analysis.sections.operating_model.body","assertion":"Arcade Mode sells Ticket packs, starts six-player tables when full and pays Badges under a posted schedule.","value":"Arcade Mode sells Ticket packs, starts six-player tables when full and pays Badges under a posted schedule.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:decentral-games-poker-arcade:arcade-mode"],"evidence_locator":"Current tournament, price and payout sections.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:decentral-games-poker-arcade:section:operating_model:2","field_path":"analysis.sections.operating_model.body","assertion":"Wearables can supply Tickets across Decentral Games products, but Bag.win rewards are a separate product.","value":"Wearables can supply Tickets across Decentral Games products, but Bag.win rewards are a separate product.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:decentral-games-poker-arcade:wearables"],"evidence_locator":"Current wearable reward distinctions.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:decentral-games-poker-arcade:section:token_and_value_capture:1","field_path":"analysis.sections.token_and_value_capture.body","assertion":"Tickets and Tournament Badges are limited-use, non-transferable product units.","value":"Tickets and Tournament Badges are limited-use, non-transferable product units.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:decentral-games-poker-arcade:terms","source:decentral-games-poker-arcade:arcade-mode"],"evidence_locator":"Product terms and current game mechanics.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:decentral-games-poker-arcade:section:token_and_value_capture:2","field_path":"analysis.sections.token_and_value_capture.body","assertion":"DG, xDG and ICE migrated to BAG, a separate parent ecosystem token surface.","value":"DG, xDG and ICE migrated to BAG, a separate parent ecosystem token surface.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:decentral-games-poker-arcade:dg-token","source:decentral-games-poker-arcade:disclaimer"],"evidence_locator":"Current migration page and BAG disclaimer.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:decentral-games-poker-arcade:section:counterfactual:1","field_path":"analysis.sections.counterfactual.body","assertion":"Historical ICE incentive selling created inflation pressure and motivated design changes.","value":"Historical ICE incentive selling created inflation pressure and motivated design changes.","as_of":"2026-08-03","confidence":"medium","kind":"inference","source_ids":["source:decentral-games-poker-arcade:study"],"evidence_locator":"Independent lifecycle discussion.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:decentral-games-poker-arcade:section:counterfactual:2","field_path":"analysis.sections.counterfactual.body","assertion":"Alternative cash or free models would change monetization and legal exposure, but no causal estimate exists.","value":"Alternative cash or free models would change monetization and legal exposure, but no causal estimate exists.","as_of":"2026-08-03","confidence":"low","kind":"inference","source_ids":["source:decentral-games-poker-arcade:terms","source:decentral-games-poker-arcade:arcade-mode"],"evidence_locator":"Observed current model used to bound alternatives.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:decentral-games-poker-arcade:section:risks_and_unknowns:1","field_path":"analysis.sections.risks_and_unknowns.body","assertion":"Current Poker Arcade activity, prize liabilities and economics are not disclosed in the reviewed record.","value":"Current Poker Arcade activity, prize liabilities and economics are not disclosed in the reviewed record.","as_of":"2026-08-03","confidence":"high","kind":"unknown","source_ids":["source:decentral-games-poker-arcade:product","source:decentral-games-poker-arcade:arcade-mode"],"evidence_locator":"Product pages disclose mechanics rather than operating results.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:decentral-games-poker-arcade:section:risks_and_unknowns:2","field_path":"analysis.sections.risks_and_unknowns.body","assertion":"No product-specific gaming licence was verified and the disclaimer denies regulatory approval of its information.","value":"No product-specific gaming licence was verified and the disclaimer denies regulatory approval of its information.","as_of":"2026-08-03","confidence":"high","kind":"unknown","source_ids":["source:decentral-games-poker-arcade:terms","source:decentral-games-poker-arcade:disclaimer"],"evidence_locator":"Legal terms and disclaimer boundary.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:decentral-games-poker-arcade:section:lifecycle:1","field_path":"analysis.sections.lifecycle.body","assertion":"The product moved from ICE play-to-earn to the Poker Arcade successor across 2021–2024.","value":"The product moved from ICE play-to-earn to the Poker Arcade successor across 2021–2024.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:decentral-games-poker-arcade:study","source:decentral-games-poker-arcade:ice-transition"],"evidence_locator":"Independent history and dated operator transition.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:decentral-games-poker-arcade:section:lifecycle:2","field_path":"analysis.sections.lifecycle.body","assertion":"Current docs show a surviving arcade product but not current commercial performance.","value":"Current docs show a surviving arcade product but not current commercial performance.","as_of":"2026-08-03","confidence":"medium","kind":"inference","source_ids":["source:decentral-games-poker-arcade:product","source:decentral-games-poker-arcade:arcade-mode"],"evidence_locator":"Current operator product surface and evidence gaps.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:decentral-games-poker-arcade:section:outlook_and_watch:1","field_path":"analysis.sections.outlook_and_watch.body","assertion":"Poker success depends on simultaneous player density and repeat table formation.","value":"Poker success depends on simultaneous player density and repeat table formation.","as_of":"2026-08-03","confidence":"medium","kind":"inference","source_ids":["source:decentral-games-poker-arcade:arcade-mode","source:decentral-games-poker-arcade:study"],"evidence_locator":"Tournament start mechanics and historical poker engagement.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:decentral-games-poker-arcade:section:outlook_and_watch:2","field_path":"analysis.sections.outlook_and_watch.body","assertion":"No current public series supports a growth, profitability or failure forecast.","value":"No current public series supports a growth, profitability or failure forecast.","as_of":"2026-08-03","confidence":"high","kind":"unknown","source_ids":["source:decentral-games-poker-arcade:product","source:decentral-games-poker-arcade:arcade-mode"],"evidence_locator":"Current evidence gap.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:decentral-games-poker-arcade:event:ice-launch","field_path":"events[event:decentral-games-poker-arcade:ice-launch]","assertion":"ICE Poker launched during October 2021; the source provides month precision.","value":"2021-10-01","as_of":"2021-10-01","confidence":"high","kind":"fact","source_ids":["source:decentral-games-poker-arcade:study"],"evidence_locator":"Independent lifecycle history.","support_direction":"supports","note":"Source precision: month.","review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:decentral-games-poker-arcade:event:arcade-launch","field_path":"events[event:decentral-games-poker-arcade:arcade-launch]","assertion":"The separate web and mobile ICE Poker Arcade launched during September 2022; the source provides month precision.","value":"2022-09-01","as_of":"2022-09-01","confidence":"high","kind":"fact","source_ids":["source:decentral-games-poker-arcade:study"],"evidence_locator":"Independent lifecycle history.","support_direction":"supports","note":"Source precision: month.","review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:decentral-games-poker-arcade:event:poker-arcade-transition","field_path":"events[event:decentral-games-poker-arcade:poker-arcade-transition]","assertion":"ICE Poker became Poker Arcade and Challenge Mode was phased out.","value":"2024-04-29","as_of":"2024-04-29","confidence":"high","kind":"fact","source_ids":["source:decentral-games-poker-arcade:ice-transition"],"evidence_locator":"Dated official transition notice.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}}],"freshness":{"state":"current","last_reviewed_at":"2026-08-03T19:31:32Z","next_review_at":"2026-08-10T19:31:32Z","field_reviews":[]},"quality":{"publication_state":"review","completeness_pct":100,"confidence":"medium","unsourced_fields":["current_active_players","current_hands_and_tournaments","ticket_sales","prize_liabilities","gaming_licence","product_revenue"]},"extensions":{"legacy_origin":"casino_syntheses.outlook","identity_boundary":"This profile covers Poker Arcade only. It is not Bag.win, not the Decentraland Casino, and not every Decentral Games product or token surface.","metric_boundary":"Ticket prices and historical ICE Poker visits are product context, not current wagers, active Poker Arcade users, revenue, prize liabilities or solvency.","explicit_unknowns":["current concurrent players and active tables","hands and tournaments per day","ticket sales and prize cost","current product licence and geographic legality","current BAG economic contribution to Poker Arcade"],"methodology_notes":["Historical ICE Poker activity is not relabeled as current Poker Arcade usage.","Operator language that the game is available worldwide is not treated as proof of legality in every jurisdiction."]}}');

INSERT INTO _casino_wave_a_profiles_0087 (case_id, canonical_profile) VALUES ('overtime', '{"schema":"chaindump-entity-profile","version":1,"identity":{"id":"web3_casino:overtime","type":"web3_casino","slug":"overtime","name":"Overtime","aliases":["Overtime Markets"]},"classification":{"subtype":"onchain sportsbook protocol","tags":["sportsbook","amm","liquidity_pools","noncustodial"],"chains":["Optimism","Arbitrum","Base","Polygon"],"jurisdictions":[]},"status":{"operating_state":"operating","as_of":"2026-08-03","claim_ids":["claim:overtime:status"]},"outcome":{"label":"operating_established","as_of":"2026-08-03","rule_id":"casino-lifecycle-evidence-v1","confidence":"medium","claim_ids":["claim:overtime:outcome"]},"analysis":{"sections":{"what_it_is":{"body":"Overtime is a noncustodial sports-market protocol and customer application built around automated market makers. Bettors trade against pools funded by third-party liquidity providers rather than against a conventional sportsbook balance sheet. Smart contracts collateralize positions and settle outcomes using Chainlink-supplied data and governance rules. The official application is one distribution surface; integrations can use the same liquidity. This is a pool-versus-peer model, not pure peer-to-peer matching and not a licensed sportsbook simply because contracts are public.","as_of":"2026-08-03","claim_ids":["claim:overtime:section:what_it_is:1","claim:overtime:section:what_it_is:2"]},"what_happened":{"body":"Overtime grew out of Thales’ positional markets. The original Ethereum orderbook design struggled with gas cost and market-maker usability, so Thales introduced an AMM on Optimism. Overtime V1 then applied that approach to sports, but creating a tokenized contract for each market did not scale to large schedules, parlays or live betting. V2 moved market and odds data into a Merkle-based architecture while retaining onchain collateral and settlement. By the 2026-08-03 snapshot, DefiLlama tracked about $1.03 million of liquidity and $119,123 of fees over 30 days.","as_of":"2026-08-03","claim_ids":["claim:overtime:section:what_happened:1","claim:overtime:section:what_happened:2"]},"why_this_outcome":{"body":"The protocol solved two cold-start problems at once: bettors receive quotes without waiting for a matching peer, and applications can reuse shared liquidity instead of building a sportsbook balance sheet. Lower-cost L2 execution and wallet/social login reduce some onchain friction. Those choices help explain continued operation and measurable fee activity. They do not prove that demand is organic or profitable. LPs take the house side and can lose when bettors win, while incentives, token discounts and rewards can rent activity. Sustainable success requires repeat bettors, risk-adjusted LP returns and enough market-level depth after incentives.","as_of":"2026-08-03","claim_ids":["claim:overtime:section:why_this_outcome:1","claim:overtime:section:why_this_outcome:2"]},"strategic_choices":{"body":"Overtime chose an AMM with risk caps rather than an orderbook, providing immediate quotes while concentrating pricing and loss exposure in the pools. It chose third-party LP collateral, so users can “be the house” and the protocol does not need to fund every bet itself. It moved to V2’s Merkle architecture to support more markets and live products, trading some fully onchain market creation for scalability. It deployed across several L2s and uses Chainlink data, broadening distribution while adding chain, oracle and liquidity fragmentation. Governance is delegated to OVER holders and an elected council rather than an identified bookmaker.","as_of":"2026-08-03","claim_ids":["claim:overtime:section:strategic_choices:1","claim:overtime:section:strategic_choices:2"]},"operating_model":{"body":"This is a pool-versus-peer operating model. A bettor selects a market and collateral on the official app. The AMM quotes a price within market risk limits, and a smart contract escrows enough collateral to pay a winning position. Third-party liquidity providers deposit USDC, WETH or cbBTC into weekly pools; their capital takes the house side across supported bets and their withdrawal settles after the active round. Chainlink and approved data providers feed events and results, while governance sets rules and resolves policy changes. The protocol can look peer-to-peer when opposite flow balances exposure, but LP capital remains the counterparty when it does not.","as_of":"2026-08-03","claim_ids":["claim:overtime:section:operating_model:1","claim:overtime:section:operating_model:2"]},"token_and_value_capture":{"body":"OVER is the protocol’s governance token and can be used as betting collateral with a pricing incentive. Holders elect the Overtime Council, and current DefiLlama methodology says AMM and LP performance fees are used for OVER buybacks. That is a documented mechanism, not audited proof that every fee reached a buyback, that tokens were burned, or that holders received cash. The 30-day fee observation was $119,123, but fees are not net income and TVL is not token value capture. Token supply, buyback execution, treasury spending and the effect of incentive programs require separate measurement.","as_of":"2026-08-03","claim_ids":["claim:overtime:section:token_and_value_capture:1","claim:overtime:section:token_and_value_capture:2"]},"counterfactual":{"body":"A traditional custodial sportsbook could hide wallet and chain complexity and centralize customer support, but it would reintroduce custody, withdrawal and balance-sheet risk. A pure orderbook could move pricing to traders and reduce LP directional exposure, while recreating the liquidity cold start that Thales encountered. Focusing on one chain could deepen a single pool and simplify operations, but would narrow distribution. Removing OVER would simplify incentives and governance, although the evidence does not isolate whether the token currently attracts durable bettors or LP capital.","as_of":"2026-08-03","claim_ids":["claim:overtime:section:counterfactual:1","claim:overtime:section:counterfactual:2"]},"risks_and_unknowns":{"body":"LPs can lose when bettors win, and weekly withdrawal timing means collateral remains exposed through the current round. Bettors depend on contracts, supported chains, oracle data, governance decisions and the official interface even without conventional custody. Prohibited jurisdictions include the United States and several other countries; “permissionless” describes software access, not legal permission. Current TVL does not prove that every market is deep or that all winning claims can execute without slippage or delay. Unique bettors, retention, subsidy-adjusted demand, pool concentration, audited buybacks and legal responsibility remain unknown.","as_of":"2026-08-03","claim_ids":["claim:overtime:section:risks_and_unknowns:1","claim:overtime:section:risks_and_unknowns:2"]},"lifecycle":{"body":"Thales began in 2021 with tokenized positional markets on Ethereum. High gas costs and weak orderbook market making pushed activity to an AMM on Optimism. Overtime V1 reused that design for sports, then V2 replaced one-contract-per-market tokenization with a Merkle-based system to support broader schedules, parlays and live betting. Current documentation shows a maintained protocol across Optimism, Arbitrum and Base, with additional tracked liquidity on Polygon. The 2026-08-03 API snapshot shows ongoing fees and collateral. Overtime is therefore established and operating, while long-term bettor retention and LP economics remain unresolved.","as_of":"2026-08-03","claim_ids":["claim:overtime:section:lifecycle:1","claim:overtime:section:lifecycle:2"]},"outlook_and_watch":{"body":"The base case is continued operation as a meaningful onchain sportsbook with modest collateral and measurable fee flow. Upside requires repeat bettors, growing settled wagers and strong risk-adjusted LP returns without heavy token or reward subsidies. Downside comes from an oracle or contract failure, weak pool economics, fragmented liquidity, governance error or wider geographic restrictions. Watch 7-, 30- and 90-day fees and settled wagers, active and retained bettors, market-level depth, utilization, LP returns after bettor payouts, withdrawal completion, OVER buybacks and supply, oracle disputes, contract upgrades, chain concentration and terms changes.","as_of":"2026-08-03","claim_ids":["claim:overtime:section:outlook_and_watch:1","claim:overtime:section:outlook_and_watch:2"]}}},"metrics":[{"id":"metric:overtime:liquidity:2026-08-03T18:13:23Z","dimension":"liquidity","label":"Tracked protocol liquidity","value":1026639,"unit":"usd","currency":"USD","window":{"start":null,"end":"2026-08-03T18:13:23Z","definition":"point_in_time"},"as_of":"2026-08-03T18:13:23Z","method":"DefiLlama protocol adapter","scope":{"product":"Overtime","chains":["Optimism","Arbitrum","Base","Polygon"]},"formula":null,"raw_input_ids":[],"claim_ids":["claim:overtime:metric:liquidity"],"quality_flags":["lp_collateral_not_wagers","not_market_depth","not_solvency"]},{"id":"metric:overtime:fees-7d:2026-08-03T19:31:32Z","dimension":"fees","label":"Estimated protocol fees, rolling 7 days","value":19911,"unit":"usd","currency":"USD","window":{"start":null,"end":"2026-08-03T19:31:32Z","definition":"rolling_7d"},"as_of":"2026-08-03T19:31:32Z","method":"DefiLlama AMM and LP performance-fee adapter","scope":{},"formula":null,"raw_input_ids":[],"claim_ids":["claim:overtime:metric:fees-7d"],"quality_flags":["aggregator_estimate","not_profit","not_wager_volume"]},{"id":"metric:overtime:fees-30d:2026-08-03T19:31:32Z","dimension":"fees","label":"Estimated protocol fees, rolling 30 days","value":119123,"unit":"usd","currency":"USD","window":{"start":null,"end":"2026-08-03T19:31:32Z","definition":"rolling_30d"},"as_of":"2026-08-03T19:31:32Z","method":"DefiLlama AMM and LP performance-fee adapter","scope":{},"formula":null,"raw_input_ids":[],"claim_ids":["claim:overtime:metric:fees-30d"],"quality_flags":["aggregator_estimate","not_profit","not_wager_volume"]}],"events":[{"id":"event:overtime:current-snapshot","type":"market_observation","date":"2026-08-03","description":"Current APIs reported $1.03 million of tracked liquidity and $119,123 of rolling 30-day fees.","claim_ids":["claim:overtime:event:current-snapshot"],"date_precision":"day"}],"sources":[{"id":"source:overtime:product","title":"What is Overtime?","url":"https://docs.overtime.io/","publisher":"Overtime DAO","published_at":null,"accessed_at":"2026-08-03T19:31:32Z","archive_url":null,"tier":"B","role":"primary","access_state":"reachable","checked_at":"2026-08-03T19:31:32Z","content_hash":null,"evidence_locator":"Current documentation describes the sportsbook, wallet flow, smart contracts and oracle dependencies.","resolving":true},{"id":"source:overtime:how","title":"How Overtime Works","url":"https://docs.overtime.io/learn-about-overtime/how-overtime-works","publisher":"Overtime DAO","published_at":null,"accessed_at":"2026-08-03T19:31:32Z","archive_url":null,"tier":"B","role":"primary","access_state":"reachable","checked_at":"2026-08-03T19:31:32Z","content_hash":null,"evidence_locator":"Current architecture describes pool-versus-peer liquidity and deployed networks.","resolving":true},{"id":"source:overtime:amm","title":"Overtime AMM and Liquidity Mechanics","url":"https://docs.overtime.io/learn-about-overtime/overtime-amm-and-liquidity-mechanics","publisher":"Overtime DAO","published_at":null,"accessed_at":"2026-08-03T19:31:32Z","archive_url":null,"tier":"B","role":"primary","access_state":"reachable","checked_at":"2026-08-03T19:31:32Z","content_hash":null,"evidence_locator":"Current AMM page documents risk caps, LP exposure and OVER collateral incentives.","resolving":true},{"id":"source:overtime:lp","title":"Providing Liquidity to Overtime","url":"https://docs.overtime.io/learn-about-overtime/providing-liquidity-to-overtime","publisher":"Overtime DAO","published_at":null,"accessed_at":"2026-08-03T19:31:32Z","archive_url":null,"tier":"B","role":"primary","access_state":"reachable","checked_at":"2026-08-03T19:31:32Z","content_hash":null,"evidence_locator":"LP guide describes seven-day rounds, loss exposure, supported collateral and withdrawal timing.","resolving":true},{"id":"source:overtime:governance","title":"Overtime Governance","url":"https://docs.overtime.io/learn-about-overtime/overtime-governance","publisher":"Overtime DAO","published_at":null,"accessed_at":"2026-08-03T19:31:32Z","archive_url":null,"tier":"B","role":"primary","access_state":"reachable","checked_at":"2026-08-03T19:31:32Z","content_hash":null,"evidence_locator":"Governance page describes elected council epochs and OIP contract changes.","resolving":true},{"id":"source:overtime:history","title":"History of Overtime","url":"https://docs.overtime.io/learn-about-overtime/history-of-overtime","publisher":"Overtime DAO","published_at":null,"accessed_at":"2026-08-03T19:31:32Z","archive_url":null,"tier":"B","role":"primary","access_state":"reachable","checked_at":"2026-08-03T19:31:32Z","content_hash":null,"evidence_locator":"History explains the Thales origin, L1/orderbook limits and V2 Merkle architecture pivot.","resolving":true},{"id":"source:overtime:terms","title":"Terms of Use","url":"https://docs.overtime.io/resources/terms-of-use","publisher":"Overtime DAO","published_at":null,"accessed_at":"2026-08-03T19:31:32Z","archive_url":null,"tier":"A","role":"primary","access_state":"reachable","checked_at":"2026-08-03T19:31:32Z","content_hash":null,"evidence_locator":"Terms list prohibited jurisdictions and state that no developer or entity supplies a universal licence.","resolving":true},{"id":"source:overtime:llama-tvl","title":"Overtime protocol TVL API","url":"https://api.llama.fi/protocol/overtime","publisher":"DefiLlama","published_at":null,"accessed_at":"2026-08-03T19:31:32Z","archive_url":null,"tier":"B","role":"aggregator","access_state":"reachable","checked_at":"2026-08-03T19:31:32Z","content_hash":null,"evidence_locator":"API snapshot returned current protocol liquidity and chain allocations.","resolving":true},{"id":"source:overtime:llama-fees","title":"Overtime fee API","url":"https://api.llama.fi/summary/fees/overtime?dataType=dailyFees","publisher":"DefiLlama","published_at":null,"accessed_at":"2026-08-03T19:31:32Z","archive_url":null,"tier":"B","role":"aggregator","access_state":"reachable","checked_at":"2026-08-03T19:31:32Z","content_hash":null,"evidence_locator":"API snapshot returned rolling fee totals and its AMM/LP-fee methodology.","resolving":true}],"claims":[{"id":"claim:overtime:status","field_path":"status.operating_state","assertion":"Overtime was operating at the review date.","value":"operating","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:overtime:product","source:overtime:llama-tvl","source:overtime:llama-fees"],"evidence_locator":"Current product documentation plus current liquidity and fee API observations.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:overtime:outcome","field_path":"outcome.label","assertion":"Overtime is classified operating established as of 2026-08-03.","value":"operating_established","as_of":"2026-08-03","confidence":"medium","kind":"inference","source_ids":["source:overtime:product","source:overtime:llama-tvl","source:overtime:llama-fees"],"evidence_locator":"Maintained product, multi-chain liquidity and current fee activity; no audited profitability or retained-bettor series.","support_direction":"supports","note":"Lifecycle classification, not a claim of profitability, solvency, legality in every market, or one exclusive cause.","review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:overtime:section:what_it_is:1","field_path":"analysis.sections.what_it_is.body","assertion":"Overtime uses smart contracts, external data and third-party LP pools for sports markets.","value":"Overtime uses smart contracts, external data and third-party LP pools for sports markets.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:overtime:how","source:overtime:product"],"evidence_locator":"Current architecture and product documentation.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:overtime:section:what_it_is:2","field_path":"analysis.sections.what_it_is.body","assertion":"The interface prohibits listed jurisdictions and no universal licence was verified.","value":"The interface prohibits listed jurisdictions and no universal licence was verified.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:overtime:terms"],"evidence_locator":"Current terms and restrictions.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:overtime:section:what_happened:1","field_path":"analysis.sections.what_happened.body","assertion":"Overtime moved from tokenized V1 markets to a Merkle-based V2 to improve scale and product breadth.","value":"Overtime moved from tokenized V1 markets to a Merkle-based V2 to improve scale and product breadth.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:overtime:history"],"evidence_locator":"Official architecture history.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:overtime:section:what_happened:2","field_path":"analysis.sections.what_happened.body","assertion":"DefiLlama reported current liquidity and 30-day fees at the review snapshot.","value":"DefiLlama reported current liquidity and 30-day fees at the review snapshot.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:overtime:llama-tvl","source:overtime:llama-fees"],"evidence_locator":"Independent API observations.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:overtime:section:why_this_outcome:1","field_path":"analysis.sections.why_this_outcome.body","assertion":"Shared LP liquidity and L2 execution reduce matching and transaction friction.","value":"Shared LP liquidity and L2 execution reduce matching and transaction friction.","as_of":"2026-08-03","confidence":"medium","kind":"inference","source_ids":["source:overtime:how","source:overtime:amm"],"evidence_locator":"Current pool-versus-peer mechanics.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:overtime:section:why_this_outcome:2","field_path":"analysis.sections.why_this_outcome.body","assertion":"Current data do not establish organic retention, LP net returns or operator profit.","value":"Current data do not establish organic retention, LP net returns or operator profit.","as_of":"2026-08-03","confidence":"high","kind":"unknown","source_ids":["source:overtime:lp","source:overtime:llama-fees"],"evidence_locator":"LP loss disclosure and independent aggregate limits.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:overtime:section:strategic_choices:1","field_path":"analysis.sections.strategic_choices.body","assertion":"The AMM, LP pools, V2 architecture and multi-chain deployment are deliberate operating choices.","value":"The AMM, LP pools, V2 architecture and multi-chain deployment are deliberate operating choices.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:overtime:amm","source:overtime:lp","source:overtime:history"],"evidence_locator":"Current mechanics and lifecycle history.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:overtime:section:strategic_choices:2","field_path":"analysis.sections.strategic_choices.body","assertion":"OVER holders elect a council that approves proposals and contract changes.","value":"OVER holders elect a council that approves proposals and contract changes.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:overtime:governance","source:overtime:terms"],"evidence_locator":"Governance and terms documentation.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:overtime:section:operating_model:1","field_path":"analysis.sections.operating_model.body","assertion":"LPs provide weekly-round collateral and bear bettor-win and smart-contract risk.","value":"LPs provide weekly-round collateral and bear bettor-win and smart-contract risk.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:overtime:lp"],"evidence_locator":"Current liquidity guide.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:overtime:section:operating_model:2","field_path":"analysis.sections.operating_model.body","assertion":"The AMM manages pool-versus-peer risk and relies on Chainlink and governance for market data and rules.","value":"The AMM manages pool-versus-peer risk and relies on Chainlink and governance for market data and rules.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:overtime:amm","source:overtime:product"],"evidence_locator":"AMM and product mechanics.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:overtime:section:token_and_value_capture:1","field_path":"analysis.sections.token_and_value_capture.body","assertion":"OVER supplies governance and documented collateral incentives.","value":"OVER supplies governance and documented collateral incentives.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:overtime:governanc