,{"id":"claim:overtime:section:risks_and_unknowns:1","field_path":"analysis.sections.risks_and_unknowns.body","assertion":"LP loss, contract, oracle, governance and withdrawal-timing risks are documented.","value":"LP loss, contract, oracle, governance and withdrawal-timing risks are documented.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:overtime:lp","source:overtime:product"],"evidence_locator":"Current risk and operating mechanics.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:overtime:section:risks_and_unknowns:2","field_path":"analysis.sections.risks_and_unknowns.body","assertion":"Jurisdiction restrictions and commercial measurement gaps prevent a universal success claim.","value":"Jurisdiction restrictions and commercial measurement gaps prevent a universal success claim.","as_of":"2026-08-03","confidence":"high","kind":"unknown","source_ids":["source:overtime:terms","source:overtime:llama-tvl","source:overtime:llama-fees"],"evidence_locator":"Terms and aggregate-data limits.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:overtime:section:lifecycle:1","field_path":"analysis.sections.lifecycle.body","assertion":"The product passed through orderbook, AMM, sports V1 and scalable V2 stages.","value":"The product passed through orderbook, AMM, sports V1 and scalable V2 stages.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:overtime:history"],"evidence_locator":"Official lifecycle history.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:overtime:section:lifecycle:2","field_path":"analysis.sections.lifecycle.body","assertion":"Current documentation and APIs show an operating protocol with live collateral and fees.","value":"Current documentation and APIs show an operating protocol with live collateral and fees.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:overtime:product","source:overtime:llama-tvl","source:overtime:llama-fees"],"evidence_locator":"Current product and data observations.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:overtime:section:outlook_and_watch:1","field_path":"analysis.sections.outlook_and_watch.body","assertion":"Current fees and collateral support continued operation but not a profitability forecast.","value":"Current fees and collateral support continued operation but not a profitability forecast.","as_of":"2026-08-03","confidence":"medium","kind":"inference","source_ids":["source:overtime:llama-tvl","source:overtime:llama-fees"],"evidence_locator":"Current independent aggregates and their limits.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:overtime:section:outlook_and_watch:2","field_path":"analysis.sections.outlook_and_watch.body","assertion":"Retention, market depth, LP net returns and buyback execution are the decisive missing signals.","value":"Retention, market depth, LP net returns and buyback execution are the decisive missing signals.","as_of":"2026-08-03","confidence":"high","kind":"unknown","source_ids":["source:overtime:lp","source:overtime:amm","source:overtime:governance"],"evidence_locator":"Documented risk-bearing and token mechanics.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:overtime:metric:liquidity","field_path":"metrics[metric:overtime:liquidity:2026-08-03T18:13:23Z].value","assertion":"Tracked protocol liquidity was 1026639 USD for the stated scope and window.","value":1026639,"as_of":"2026-08-03T18:13:23Z","confidence":"high","kind":"fact","source_ids":["source:overtime:llama-tvl"],"evidence_locator":"Provider response retrieved and