_review_at":"2026-08-10T19:31:32Z","field_reviews":[]},"quality":{"publication_state":"review","completeness_pct":100,"confidence":"medium","unsourced_fields":["active_bettors","retained_bettors","settled_wagers_by_chain","market_depth","lp_net_returns","audited_financials","gaming_licence"]},"extensions":{"legacy_origin":"casino_syntheses.outlook","identity_boundary":"This profile covers the Overtime protocol and official application. Third-party integrations, odds providers and Thales history are separate operating surfaces.","metric_boundary":"Tracked TVL is LP collateral, not wagering volume, not executable depth for every market, not customer reserves, and not solvency. Fees are adapter estimates, not audited profit.","explicit_unknowns":["unique and retained bettors","settled wagers by chain","market-level depth and slippage","risk-adjusted LP returns","audited buyback execution and token value capture","legal operator and licence by interface"],"methodology_notes":["Pool collateral and fee observations are not treated as operator solvency or profit.","Official permissionless language is not treated as a universal legal right to use the interface."]}}');

INSERT INTO _casino_wave_a_profiles_0087 (case_id, canonical_profile) VALUES ('sx-bet', '{"schema":"chaindump-entity-profile","version":1,"identity":{"id":"web3_casino:sx-bet","type":"web3_casino","slug":"sx-bet","name":"SX Bet","aliases":["SX.bet"]},"classification":{"subtype":"peer-to-peer betting exchange","tags":["sports_betting","order_book","escrow","noncustodial"],"chains":["SX Rollup"],"jurisdictions":["Anjouan licence claimed by operator"]},"status":{"operating_state":"operating","as_of":"2026-08-03","claim_ids":["claim:sx-bet:status"]},"outcome":{"label":"operating_token_transition","as_of":"2026-08-03","rule_id":"casino-lifecycle-evidence-v1","confidence":"high","claim_ids":["claim:sx-bet:outcome"]},"analysis":{"sections":{"what_it_is":{"body":"SX Bet is a sports betting exchange in which makers post odds and takers accept them through an open orderbook. Both sides’ USDC is locked in an escrow contract and a reported result determines the payout. CRGC Management Ltd is the service provider named in the current terms; Nextgen Blockchain Technologies Ltd owns the proprietary service and intellectual property. The operator says CRGC is licensed in Anjouan, but local legality remains user-specific and the licence claim was not independently verified from an authority register.","as_of":"2026-08-03","claim_ids":["claim:sx-bet:section:what_it_is:1","claim:sx-bet:section:what_it_is:2"]},"what_happened":{"body":"SX Bet continued operating through 2026 while making a major token and infrastructure reset. Current terms record a May 15, 2026 snapshot of SX balances and say the network is moving to a gasless architecture in which SX will lose its primary gas role. Eligible users may receive non-cash USDC Bet Credits, subject to KYC, geography and other checks. DefiLlama’s 2026-08-03 snapshot reported about $2.94 million of matched bets over 24 hours and $86.39 million over 30 days. That is real exchange activity, but it is not customer assets, revenue or profit.","as_of":"2026-08-03","claim_ids":["claim:sx-bet:section:what_happened:1","claim:sx-bet:section:what_happened:2"]},"why_this_outcome":{"body":"SX Bet attracts price-sensitive bettors by letting users post odds, offering zero fees on straight bets and exposing an API for professional makers. The orderbook can reward sharp liquidity instead of banning winning users, and escrow reduces conventional operator custody. Those choices help explain meaningful matched volume. The same model depends on enough two-sided liquidity, reliable market creation and result reporting. The token sunset suggests that running a dedicated gas-token network added complexity that the customer product did not need. Product activity survived because USDC wagering and exchange liquidity are separable from SX token demand.","as_of":"2026-08-03","claim_ids":["claim:sx-bet:section:why_this_outcome:1","claim:sx-bet:section:why_this_outcome:2"]},"strategic_choices":{"body":"SX chose a peer-to-peer orderbook instead of setting house odds, making market makers and order-book depth central to product quality. It chose USDC as the primary wagering asset and smart-contract escrow for matched bets, reducing token-price exposure during play. It charges no fee on straight bets and 5% on winning parlays, using a narrow monetization path to compete on price. In 2026 it chose to sunset SX and move away from a native-gas network toward gasless infrastructure, protecting the customer exchange from token friction while severing the token’s former core utility.","as_of":"2026-08-03","claim_ids":["claim:sx-bet:section:strategic_choices:1","claim:sx-bet:section:strategic_choices:2"]},"operating_model":{"body":"A maker signs an order specifying outcome, stake and odds. A taker fills it; both stakes move into escrow until a reporter submits the event result onchain. The contract pays the winner or returns stakes on a void. SX Bet supplies the interface, market registry, maintenance controls and rule system, while market makers supply quotes. Straight bets carry no trading fee; a winning peer-to-peer parlay carries a 5% fee. Users can log in with wallets or social accounts, so noncustodial settlement coexists with an operator-controlled frontend and eligibility process.","as_of":"2026-08-03","claim_ids":["claim:sx-bet:section:operating_model:1","claim:sx-bet:section:operating_model:2"]},"token_and_value_capture":{"body":"SX was the SX Network gas token and was historically used for staking and related network actions. The May 15, 2026 sunset terms say the new architecture will not require SX as native gas. USDC Bet Credits allocated from the snapshot are not USDC and not cash, stablecoins, tokens, deposits or e-money; they are not withdrawable, transferable or redeemable. The program offers no token redemption or buyback, and the $0.015 reference is not represented as fair market value. Product value capture now centers on winning-parlay fees, while post-sunset rights for SX holders are not established.","as_of":"2026-08-03","claim_ids":["claim:sx-bet:section:token_and_value_capture:1","claim:sx-bet:section:token_and_value_capture:2"]},"counterfactual":{"body":"Keeping SX as mandatory gas could preserve token utility, but would continue wallet friction and tie exchange use to token liquidity. A house-banked sportsbook could guarantee quotes on selected markets, while adding balance-sheet and reserve risk that the orderbook avoids. Charging straight-bet fees could create broader revenue, but might weaken the price advantage used to attract traders. The gasless plan is therefore a product-first trade: simplify the betting experience and accept that the original token thesis did not remain central. No evidence estimates what volume or retention would have been under the alternatives.","as_of":"2026-08-03","claim_ids":["claim:sx-bet:section:counterfactual:1","claim:sx-bet:section:counterfactual:2"]},"risks_and_unknowns":{"body":"Liquidity is the central product risk: large matched volume can coexist with thin depth, wide spreads or concentrated market makers. Escrow reduces conventional custody but does not remove contract, reporter, market-rule, frontend or access risk. Current terms exclude the United States and many other jurisdictions and reserve eligibility checks for the token transition. CRGC’s Anjouan licence is an operator claim; independent reporting raises broader questions about that licensing system but is not evidence of SX-specific wrongdoing. Unique bettors, customer asset coverage, audited fees and the exact network-deprecation path remain unknown.","as_of":"2026-08-03","claim_ids":["claim:sx-bet:section:risks_and_unknowns:1","claim:sx-bet:section:risks_and_unknowns:2"]},"lifecycle":{"body":"SX Bet is an active product in the middle of a structural reset, not a closed exchange. Its original model paired a peer-to-peer betting exchange with SX Network and the SX gas token. On May 15, 2026, the operator took the token-holder snapshot and introduced terms for the SX token sunset, a gasless architecture and planned deprecation of SX Network. Users have until August 15, 2026 to accept the Bet Credit terms. During the transition, the exchange continued producing matched volume. The correct lifecycle call is active product, sunset token utility and migrating chain infrastructure.","as_of":"2026-08-03","claim_ids":["claim:sx-bet:section:lifecycle:1","claim:sx-bet:section:lifecycle:2"]},"outlook_and_watch":{"body":"The base case is continued exchange operation after the gasless migration, with USDC and market-maker liquidity carrying more weight than SX. Upside requires stable or rising matched volume, deeper books, repeat bettors and reliable settlement while the migration removes friction. Downside is market-maker concentration, loss of liquidity, reporter or contract failure, licence or geographic pressure, or a migration that disrupts balances and integrations. Watch 7-, 30- and 90-day matched volume, order-book depth and spreads, repeat bettors, parlay fees, open interest, settlement disputes, token-credit uptake, chain deprecation milestones and CRGC’s licence status.","as_of":"2026-08-03","claim_ids":["claim:sx-bet:section:outlook_and_watch:1","claim:sx-bet:section:outlook_and_watch:2"]}}},"metrics":[{"id":"metric:sx-bet:wagers-24h:2026-08-03T19:31:32Z","dimension":"wagers","label":"Matched betting volume, rolling 24 hours","value":2936713,"unit":"usd","currency":"USD","window":{"start":null,"end":"2026-08-03T19:31:32Z","definition":"rolling_24h"},"as_of":"2026-08-03T19:31:32Z","method":"DefiLlama adapter using SX public analytics","scope":{"product":"SX Bet","chain":"SX Rollup"},"formula":null,"raw_input_ids":[],"claim_ids":["claim:sx-bet:metric:wagers-24h"],"quality_flags":["matched_volume_not_deposits","not_revenue","not_unique_users","not_solvency"]},{"id":"metric:sx-bet:wagers-7d:2026-08-03T19:31:32Z","dimension":"wagers","label":"Matched betting volume, rolling 7 days","value":14157170,"unit":"usd","currency":"USD","window":{"start":null,"end":"2026-08-03T19:31:32Z","definition":"rolling_7d"},"as_of":"2026-08-03T19:31:32Z","method":"DefiLlama adapter using SX public analytics","scope":{"product":"SX Bet","chain":"SX Rollup"},"formula":null,"raw_input_ids":[],"claim_ids":["claim:sx-bet:metric:wagers-7d"],"quality_flags":["matched_volume_not_deposits","not_revenue","not_unique_users"]},{"id":"metric:sx-bet:wagers-30d:2026-08-03T19:31:32Z","dimension":"wagers","label":"Matched betting volume, rolling 30 days","value":86392972,"unit":"usd","currency":"USD","window":{"start":null,"end":"2026-08-03T19:31:32Z","definition":"rolling_30d"},"as_of":"2026-08-03T19:31:32Z","method":"DefiLlama adapter using SX public analytics","scope":{"product":"SX Bet","chain":"SX Rollup"},"formula":null,"raw_input_ids":[],"claim_ids":["claim:sx-bet:metric:wagers-30d"],"quality_flags":["matched_volume_not_deposits","not_revenue","not_unique_users"]},{"id":"metric:sx-bet:fees-30d:2026-08-03T19:31:32Z","dimension":"fees","label":"Estimated winning-parlay fees, rolling 30 days","value":984.39,"unit":"usd","currency":"USD","window":{"start":null,"end":"2026-08-03T19:31:32Z","definition":"rolling_30d"},"as_of":"2026-08-03T19:31:32Z","method":"DefiLlama parlay-fee adapter","scope":{"product":"SX Bet","chain":"SX Rollup"},"formula":null,"raw_input_ids":[],"claim_ids":["claim:sx-bet:metric:fees-30d"],"quality_flags":["aggregator_estimate","not_audited_revenue","straight_bets_fee_free"]}],"events":[{"id":"event:sx-bet:token-snapshot","type":"token_sunset","date":"2026-05-15","description":"SX Bet took the SX holder snapshot and introduced token-sunset and Bet Credit terms.","claim_ids":["claim:sx-bet:event:token-snapshot"],"date_precision":"day"},{"id":"event:sx-bet:credit-deadline","type":"terms_deadline","date":"2026-08-15","description":"The stated deadline to accept the Bet Credit terms is 2026-08-15; credits are not cash or token redemption.","claim_ids":["claim:sx-bet:event:credit-deadline"],"date_precision":"day"},{"id":"event:sx-bet:current-snapshot","type":"market_observation","date":"2026-08-03","description":"The API snapshot reported $2.94 million of matched bets over 24 hours and $86.39 million over 30 days.","claim_ids":["claim:sx-bet:event:current-snapshot"],"date_precision":"day"}],"sources":[{"id":"source:sx-bet:terms","title":"Terms and Conditions","url":"https://help.sx.bet/en/articles/3613372-terms-and-conditions","publisher":"SX Bet / CRGC Management Ltd","published_at":"2026-05-15","accessed_at":"2026-08-03T19:31:32Z","archive_url":null,"tier":"A","role":"primary","access_state":"reachable","checked_at":"2026-08-03T19:31:32Z","content_hash":null,"evidence_locator":"Current terms identify the service provider, licence claim, restrictions, token sunset and credit terms.","resolving":true},{"id":"source:sx-bet:protocol","title":"What is SX Bet?","url":"https://docs.sx.bet/developers/what-is-sx-bet","publisher":"SX Bet","published_at":"2026-03-27","accessed_at":"2026-08-03T19:31:32Z","archive_url":null,"tier":"B","role":"primary","access_state":"reachable","checked_at":"2026-08-03T19:31:32Z","content_hash":null,"evidence_locator":"Developer docs explain maker/taker orders, escrow, onchain reporting and USDC wagering.","resolving":true},{"id":"source:sx-bet:overview","title":"Introduction and Overview","url":"https://help.sx.bet/en/articles/4037276-introduction-and-overview","publisher":"SX Bet","published_at":"2026-03-02","accessed_at":"2026-08-03T19:31:32Z","archive_url":null,"tier":"B","role":"primary","access_state":"reachable","checked_at":"2026-08-03T19:31:32Z","content_hash":null,"evidence_locator":"Overview describes the peer-to-peer model and protocol controls without validating marketing superlatives.","resolving":true},{"id":"source:sx-bet:fees","title":"Fees","url":"https://docs.sx.bet/user-guides/trading/fees","publisher":"SX Bet","published_at":"2026-03-24","accessed_at":"2026-08-03T19:31:32Z","archive_url":null,"tier":"B","role":"primary","access_state":"reachable","checked_at":"2026-08-03T19:31:32Z","content_hash":null,"evidence_locator":"Fee guide documents zero single-bet fees, 5% winning-parlay fees and historical SX gas use.","resolving":true},{"id":"source:sx-bet:parlays","title":"Peer-to-Peer Parlays","url":"https://help.sx.bet/en/articles/13919339-peer-to-peer-parlays","publisher":"SX Bet","published_at":"2026-03-03","accessed_at":"2026-08-03T19:31:32Z","archive_url":null,"tier":"B","role":"primary","access_state":"reachable","checked_at":"2026-08-03T19:31:32Z","content_hash":null,"evidence_locator":"Parlay guide documents peer orders, ten-leg limit and 5% winning-parlay fee.","resolving":true},{"id":"source:sx-bet:news","title":"SX Bet News","url":"https://blog.sx.bet/news/","publisher":"SX Bet","published_at":null,"accessed_at":"2026-08-03T19:31:32Z","archive_url":null,"tier":"B","role":"primary","access_state":"reachable","checked_at":"2026-08-03T19:31:32Z","content_hash":null,"evidence_locator":"Current news index lists the token sunset and new gasless infrastructure plan.","resolving":true},{"id":"source:sx-bet:llama-volume","title":"SX Bet matched-volume API","url":"https://api.llama.fi/summary/dexs/sx-bet?dataType=dailyVolume","publisher":"DefiLlama","published_at":null,"accessed_at":"2026-08-03T19:31:32Z","archive_url":null,"tier":"B","role":"aggregator","access_state":"reachable","checked_at":"2026-08-03T19:31:32Z","content_hash":null,"evidence_locator":"API snapshot returned matched-bet volume from the protocol analytics adapter.","resolving":true},{"id":"source:sx-bet:llama-fees","title":"SX Bet fee API","url":"https://api.llama.fi/summary/fees/sx-bet?dataType=dailyFees","publisher":"DefiLlama","published_at":null,"accessed_at":"2026-08-03T19:31:32Z","archive_url":null,"tier":"B","role":"aggregator","access_state":"reachable","checked_at":"2026-08-03T19:31:32Z","content_hash":null,"evidence_locator":"API snapshot returned parlay-fee estimates and historical token-distribution methodology.","resolving":true},{"id":"source:sx-bet:anjouan-context","title":"How France’s lottery operator fuels the toxic online casino ecosystem in the Comoros","url":"https://www.lemonde.fr/en/les-decodeurs/article/2026/02/04/how-france-s-lottery-operator-fuels-the-toxic-online-casino-ecosystem-in-the-comoros_6750148_8.html","publisher":"Le Monde","published_at":"2026-02-04","accessed_at":"2026-08-03T19:31:32Z","archive_url":null,"tier":"A","role":"independent","access_state":"reachable","checked_at":"2026-08-03T19:31:32Z","content_hash":null,"evidence_locator":"Independent reporting challenges the Anjouan licensing system generally; it is not an SX-specific finding.","resolving":true}],"claims":[{"id":"claim:sx-bet:status","field_path":"status.operating_state","assertion":"SX Bet was operating at the review date.","value":"operating","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:sx-bet:terms","source:sx-bet:protocol","source:sx-bet:llama-volume"],"evidence_locator":"Current 2026 terms and protocol docs plus current matched-volume observations.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:sx-bet:outcome","field_path":"outcome.label","assertion":"SX Bet is classified operating token transition as of 2026-08-03.","value":"operating_token_transition","as_of":"2026-08-03","confidence":"high","kind":"inference","source_ids":["source:sx-bet:terms","source:sx-bet:protocol","source:sx-bet:llama-volume"],"evidence_locator":"Active exchange activity alongside an explicit SX token sunset and planned chain deprecation.","support_direction":"supports","note":"Lifecycle classification, not a claim of profitability, solvency, legality in every market, or one exclusive cause.","review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:sx-bet:section:what_it_is:1","field_path":"analysis.sections.what_it_is.body","assertion":"SX Bet uses maker/taker orders, USDC escrow and onchain result reporting.","value":"SX Bet uses maker/taker orders, USDC escrow and onchain result reporting.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:sx-bet:protocol"],"evidence_locator":"Current developer documentation.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:sx-bet:section:what_it_is:2","field_path":"analysis.sections.what_it_is.body","assertion":"Current terms name CRGC as service provider and Nextgen as technology owner.","value":"Current terms name CRGC as service provider and Nextgen as technology owner.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:sx-bet:terms"],"evidence_locator":"2026 legal terms and operator roles.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:sx-bet:section:what_happened:1","field_path":"analysis.sections.what_happened.body","assertion":"The 2026 terms establish an SX token sunset, gasless migration and planned network deprecation.","value":"The 2026 terms establish an SX token sunset, gasless migration and planned network deprecation.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:sx-bet:terms","source:sx-bet:news"],"evidence_locator":"Current legal terms and news index.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:sx-bet:section:what_happened:2","field_path":"analysis.sections.what_happened.body","assertion":"Current matched-bet volume shows an active exchange product during the transition.","value":"Current matched-bet volume shows an active exchange product during the transition.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:sx-bet:llama-volume"],"evidence_locator":"Independent API snapshot.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:sx-bet:section:why_this_outcome:1","field_path":"analysis.sections.why_this_outcome.body","assertion":"Orderbook pricing, zero straight-bet fees and API access support exchange liquidity.","value":"Orderbook pricing, zero straight-bet fees and API access support exchange liquidity.","as_of":"2026-08-03","confidence":"medium","kind":"inference","source_ids":["source:sx-bet:protocol","source:sx-bet:fees","source:sx-bet:overview"],"evidence_locator":"Current protocol and fee design.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:sx-bet:section:why_this_outcome:2","field_path":"analysis.sections.why_this_outcome.body","assertion":"The active product and token sunset are distinct lifecycle outcomes.","value":"The active product and token sunset are distinct lifecycle outcomes.","as_of":"2026-08-03","confidence":"high","kind":"inference","source_ids":["sourc