:lifecycle:1","field_path":"analysis.sections.lifecycle.body","assertion":"The active product, token sunset and planned network deprecation coexist.","value":"The active product, token sunset and planned network deprecation coexist.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:sx-bet:terms","source:sx-bet:protocol","source:sx-bet:llama-volume"],"evidence_locator":"Current legal, product and activity evidence.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:sx-bet:section:lifecycle:2","field_path":"analysis.sections.lifecycle.body","assertion":"The 2026-08-15 acceptance deadline applies to Bet Credits, not a guaranteed cash redemption.","value":"The 2026-08-15 acceptance deadline applies to Bet Credits, not a guaranteed cash redemption.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:sx-bet:terms"],"evidence_locator":"Current credit acceptance clause.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:sx-bet:section:outlook_and_watch:1","field_path":"analysis.sections.outlook_and_watch.body","assertion":"Current volume supports an operating base case but not profit, solvency or retention.","value":"Current volume supports an operating base case but not profit, solvency or retention.","as_of":"2026-08-03","confidence":"medium","kind":"inference","source_ids":["source:sx-bet:llama-volume","source:sx-bet:llama-fees"],"evidence_locator":"Independent matched-volume and fee aggregates.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:sx-bet:section:outlook_and_watch:2","field_path":"analysis.sections.outlook_and_watch.body","assertion":"Migration execution, liquidity depth and repeat bettors are the decisive next signals.","value":"Migration execution, liquidity depth and repeat bettors are the decisive next signals.","as_of":"2026-08-03","confidence":"high","kind":"unknown","source_ids":["source:sx-bet:terms","source:sx-bet:protocol"],"evidence_locator":"Current transition and exchange mechanics.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:sx-bet:metric:wagers-24h","field_path":"metrics[metric:sx-bet:wagers-24h:2026-08-03T19:31:32Z].value","assertion":"Matched betting volume, rolling 24 hours was 2936713 USD for the stated scope and window.","value":2936713,"as_of":"2026-08-03T19:31:32Z","confidence":"high","kind":"fact","source_ids":["source:sx-bet:llama-volume"],"evidence_locator":"Provider response retrieved and frozen in the research artifact.","support_direction":"supports","note":"Limits: matched_volume_not_deposits, not_revenue, not_unique_users, not_solvency.","review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:sx-bet:metric:wagers-7d","field_path":"metrics[metric:sx-bet:wagers-7d:2026-08-03T19:31:32Z].value","assertion":"Matched betting volume, rolling 7 days was 14157170 USD for the stated scope and window.","value":14157170,"as_of":"2026-08-03T19:31:32Z","confidence":"high","kind":"fact","source_ids":["source:sx-bet:llama-volume"],"evidence_locator":"Provider response retrieved and frozen in the research artifact.","support_direction":"supports","note":"Limits: matched_volume_not_deposits, not_revenue, not_unique_users.","review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:sx-bet:metric:wagers-30d","field_path":"metrics[metric:sx-bet:wagers-30d:2026-08-03T19:31:32Z].value","assertion":"Matched betting volume, rolling 30 days was 86392972 USD for the stated scope and window.","value":86392972,"as_of":"2026-08-03T19:31:32Z","confidence":"high","kind":"fact","source_ids":["source:sx-bet:llama-volume"],"evidence_locator":"Provider response retrieved and frozen in the research artifact.","support_direction":"supports","note":"Limits: matched_volume_not_deposits, not_revenue, not_unique_users.","review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:sx-bet:metric:fees-30d","field_path":"metrics[metric:sx-bet:fees-30d:2026-08-03T19:31:32Z].value","assertion":"Estimated winning-parlay fees, rolling 30 days was 984.39 USD for the stated scope and window.","value":984.39,"as_of":"2026-08-03T19:31:32Z","confidence":"high","kind":"fact","source_ids":["source:sx-bet:llama-fees"],"evidence_locator":"Provider response retrieved and frozen in the research artifact.","support_direction":"supports","note":"Limits: aggregator_estimate, not_audited_revenue, straight_bets_fee_free.","review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:sx-bet:event:token-snapshot","field_path":"events[event:sx-bet:token-snapshot]","assertion":"SX Bet took the SX holder snapshot and introduced token-sunset and Bet Credit terms.","value":"2026-05-15","as_of":"2026-05-15","confidence":"high","kind":"fact","source_ids":["source:sx-bet:terms"],"evidence_locator":"Dated current terms.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:sx-bet:event:credit-deadline","field_path":"events[event:sx-bet:credit-deadline]","assertion":"The stated deadline to accept the Bet Credit terms is 2026-08-15; credits are not cash or token redemption.","value":"2026-08-15","as_of":"2026-08-15","confidence":"high","kind":"fact","source_ids":["source:sx-bet:terms"],"evidence_locator":"Current terms deadline.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:sx-bet:event:current-snapshot","field_path":"events[event:sx-bet:current-snapshot]","assertion":"The API snapshot reported $2.94 million of matched bets over 24 hours and $86.39 million over 30 days.","value":"2026-08-03","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:sx-bet:llama-volume"],"evidence_locator":"DefiLlama API retrieved on the review date.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}}],"freshness":{"state":"current","last_reviewed_at":"2026-08-03T19:31:32Z","next_review_at":"2026-08-10T19:31:32Z","field_reviews":[]},"quality":{"publication_state":"review","completeness_pct":100,"confidence":"high","unsourced_fields":["active_bettors","retained_bettors","orderbook_depth","customer_assets","licence_authority_verification","audited_revenue"]},"extensions":{"legacy_origin":"casino_syntheses.outlook","identity_boundary":"This profile covers the SX Bet consumer exchange and its protocol. CRGC Management provides the service; Nextgen owns technology; neither role is attributed to ordinary market makers.","metric_boundary":"Matched betting volume is not deposits, customer assets, revenue, profit or solvency. The stale SX Rollup TVL point is intentionally excluded from headline metrics.","explicit_unknowns":["unique and retained bettors","open-order depth and spread history","current customer asset coverage","post-sunset SX Network timeline","independently verified licence status","audited parlay revenue"],"methodology_notes":["The operator’s Anjouan licence claim is reported as a claim; jurisdiction-wide criticism is not treated as SX-specific misconduct.","Bet Credits are not valued as assets, redemption proceeds or token consideration."]}}');

INSERT INTO _casino_wave_a_profiles_0087 (case_id, canonical_profile) VALUES ('azuro', '{"schema":"chaindump-entity-profile","version":1,"identity":{"id":"web3_casino:azuro","type":"web3_casino","slug":"azuro","name":"Azuro","aliases":["Azuro Protocol"]},"classification":{"subtype":"prediction market infrastructure","tags":["protocol_infrastructure","shared_liquidity","vamm","multi_app"],"chains":["Polygon","Gnosis","Base","Chiliz","Arbitrum","Linea"],"jurisdictions":[]},"status":{"operating_state":"operating","as_of":"2026-08-03","claim_ids":["claim:azuro:status"]},"outcome":{"label":"operating_unclassified","as_of":"2026-08-03","rule_id":"casino-lifecycle-evidence-v1","confidence":"medium","claim_ids":["claim:azuro:outcome"]},"analysis":{"sections":{"what_it_is":{"body":"Azuro is shared prediction-market infrastructure for independent applications, not a consumer sportsbook. Its smart contracts, SDK and data-provider system let frontends offer sports and other event markets while drawing from common vAMM liquidity pools. LPs fund pools; data providers create and reprice conditions and initially resolve them; apps control customer experience and distribution. AzuroDAO governs the protocol and supplies an interface, while current docs say each application is a separate entity with its own legal obligations.","as_of":"2026-08-03","claim_ids":["claim:azuro:section:what_it_is:1","claim:azuro:section:what_it_is:2"]},"what_happened":{"body":"Azuro built a multi-application, multi-chain liquidity layer rather than one betting brand. In 2026 it forced applications to migrate to V3 and said V2 would be emptied and stopped on May 8, demonstrating active development but also version dependency. On the 2026-08-03 review, DefiLlama tracked about $1.56 million of liquidity across six EVM networks. Its pool-result series showed a positive $147,317 over 30 days but losses of $65,043 over seven days and $15,294 over 24 hours. These are pool outcomes, not audited protocol company earnings.","as_of":"2026-08-03","claim_ids":["claim:azuro:section:what_happened:1","claim:azuro:section:what_happened:2"]},"why_this_outcome":{"body":"Shared liquidity lowers the cold-start cost for a new betting frontend: an application can inherit pool capacity instead of recruiting its own bookmakers. The SDK lowers integration cost, and multiple applications can compete on UX and distribution. That explains why Azuro can remain active without one dominant consumer brand. It also spreads responsibility. The protocol still needs bettors, apps, accurate data providers and LPs willing to take correlated exposure across thousands of markets. Current liquidity is modest and short-window pool results can be negative, so deployment breadth alone does not establish durable commercial success.","as_of":"2026-08-03","claim_ids":["claim:azuro:section:why_this_outcome:1","claim:azuro:section:why_this_outcome:2"]},"strategic_choices":{"body":"Azuro chose infrastructure over a canonical sportsbook, allowing independent apps to own distribution while making adoption harder to attribute. It chose singleton pools and vAMM pricing rather than separate orderbooks, improving capital reuse while exposing each LP position to many markets. It deployed across six EVM networks, widening addressable distribution but fragmenting versions, app support and liquidity. It assigns event creation, repricing and initial resolution to data providers with AzuroDAO as a last-resort arbiter. It also introduced AZUR staking and the two-year pAZUR lock to tie governance and conditional distributions to long-duration holders.","as_of":"2026-08-03","claim_ids":["claim:azuro:section:strategic_choices:1","claim:azuro:section:strategic_choices:2"]},"operating_model":{"body":"An application presents markets and sends a user’s bet to Azuro contracts. A data provider creates the underlying condition, supplies odds and later reports the result. The vAMM prices exposure against a singleton pool, so LP collateral can support many markets rather than one isolated book. Pool profit or loss flows from bettor outcomes and fee design, and one LP position is exposed across the pool’s market set. AzuroDAO governs protocol rules and can act as dispute arbiter, but the application remains responsible for customer access, branding and its own legal posture.","as_of":"2026-08-03","claim_ids":["claim:azuro:section:operating_model:1","claim:azuro:section:operating_model:2"]},"token_and_value_capture":{"body":"AZUR is an ERC-20 with a documented one-billion total supply, ecosystem, treasury, investor and contributor allocations, and long vesting schedules. Liquid AZUR can be staked into stAZUR. A holder who locks stAZUR for two years receives a transferable pAZUR NFT that is eligible for variable USDT distributions funded from protocol activity. That right does not attach automatically to every liquid AZUR token, the lock cannot be cancelled early, and returns are not guaranteed. The reviewed record does not independently verify distribution amounts, treasury spending or whether token incentives exceed realized value.","as_of":"2026-08-03","claim_ids":["claim:azuro:section:token_and_value_capture:1","claim:azuro:section:token_and_value_capture:2"]},"counterfactual":{"body":"A single Azuro-operated sportsbook would make customer metrics, revenue and legal responsibility easier to measure, but would abandon the multi-app thesis and create one interface dependency. Separate pools per app or chain could isolate risk and attribution, while worsening liquidity fragmentation. An orderbook could move price setting to market makers, but would recreate a liquidity cold start. A shorter token lock could improve flexibility while weakening the long-duration alignment pAZUR is designed to create. None of these alternatives has a causal performance estimate in the reviewed record.","as_of":"2026-08-03","claim_ids":["claim:azuro:section:counterfactual:1","claim:azuro:section:counterfactual:2"]},"risks_and_unknowns":{"body":"LPs face bettor losses, correlated exposure across many conditions, smart-contract risk and uncertain withdrawal economics. Bettors and apps depend on data providers for creation, repricing and initial resolution, with AzuroDAO as last-resort arbiter. V3’s forced migration shows that “permissionless” applications still depend on protocol version support. Azuro’s terms restrict countries including the United States and say the DAO is not a gambling operator; each app needs separate legal analysis. Current TVL and pool results do not identify users, app concentration, solvency, net LP returns or customer protection.","as_of":"2026-08-03","claim_ids":["claim:azuro:section:risks_and_unknowns:1","claim:azuro:section:risks_and_unknowns:2"]},"lifecycle":{"body":"Azuro progressed from a protocol concept to versioned production infrastructure on several EVM networks, adding SDK tooling, governance and the AZUR staking system. Its 2026 V3 release required applications to migrate within days and planned to stop V2 on May 8. Current developer surfaces and liquidity feeds show the protocol remains maintained after that migration. The lifecycle call is active infrastructure with an unclassified commercial outcome: contracts, releases and pool activity are real, but durable application demand, retained bettors, LP returns and realized token distributions are not yet demonstrated in a comparable series.","as_of":"2026-08-03","claim_ids":["claim:azuro:section:lifecycle:1","claim:azuro:section:lifecycle:2"]},"outlook_and_watch":{"body":"The base case is continued operation as a shared infrastructure layer with modest multi-chain liquidity. Upside requires more independent applications, repeat bettors, higher pool utilization and positive LP returns after losses and incentives, plus recurring pAZUR distributions. Downside is concentration in a few apps or data providers, poor LP economics, a resolution failure, another disruptive migration or tighter frontend restrictions. Watch wagers, bettors, apps and fees by chain; pool deposits, withdrawals and net returns; data-provider concentration and disputes; V3 adoption; pAZUR locks and distributions; AZUR unlocks; and the operator and licence behind each major frontend.","as_of":"2026-08-03","claim_ids":["claim:azuro:section:outlook_and_watch:1","claim:azuro:section:outlook_and_watch:2"]}}},"metrics":[{"id":"metric:azuro:liquidity:2026-08-03T18:13:23Z","dimension":"liquidity","label":"Tracked protocol liquidity","value":1563088,"unit":"usd","currency":"USD","window":{"start":null,"end":"2026-08-03T18:13:23Z","definition":"point_in_time"},"as_of":"2026-08-03T18:13:23Z","method":"DefiLlama protocol adapter","scope":{"product":"Azuro Protocol","chains":["Polygon","Gnosis","Base","Chiliz","Arbitrum","Linea"]},"formula":null,"raw_input_ids":[],"claim_ids":["claim:azuro:metric:liquidity"],"quality_flags":["pool_liquidity_not_wagers","not_users","not_operator_solvency"]},{"id":"metric:azuro:pool-result-24h:2026-08-03T19:31:32Z","dimension":"gross_gaming_revenue","label":"Pool net result, rolling 24 hours","value":-15294,"unit":"usd","currency":"USD","window":{"start":null,"end":"2026-08-03T19:31:32Z","definition":"rolling_24h"},"as_of":"2026-08-03T19:31:32Z","method":"DefiLlama settled bets minus won bets","scope":{"product":"Azuro pools","chains":["multi-chain"]},"formula":null,"raw_input_ids":[],"claim_ids":["claim:azuro:metric:pool-result-24h"],"quality_flags":["pool_result_not_company_revenue","negative_when_bettors_outperform","not_audited"]},{"id":"metric:azuro:pool-result-7d:2026-08-03T19:31:32Z","dimension":"gross_gaming_revenue","label":"Pool net result, rolling 7 days","value":-65043,"unit":"usd","currency":"USD","window":{"start":null,"end":"2026-08-03T19:31:32Z","definition":"rolling_7d"},"as_of":"2026-08-03T19:31:32Z","method":"DefiLlama settled bets minus won bets","scope":{"product":"Azuro pools","chains":["multi-chain"]},"formula":null,"raw_input_ids":[],"claim_ids":["claim:azuro:metric:pool-result-7d"],"quality_flags":["pool_result_not_company_revenue","negative_when_bettors_outperform","not_audited"]},{"id":"metric:azuro:pool-result-30d:2026-08-03T19:31:32Z","dimension":"gross_gaming_revenue","label":"Pool net result, rolling 30 days","value":147317,"unit":"usd","currency":"USD","window":{"start":null,"end":"2026-08-03T19:31:32Z","definition":"rolling_30d"},"as_of":"2026-08-03T19:31:32Z","method":"DefiLlama settled bets minus won bets","scope":{"product":"Azuro pools","chains":["multi-chain"]},"formula":null,"raw_input_ids":[],"claim_ids":["claim:azuro:metric:pool-result-30d"],"quality_flags":["pool_result_not_company_revenue","not_lp_net_return","not_audited"]}],"events":[{"id":"event:azuro:v3-migration","type":"protocol_upgrade","date":"2026-05-08","description":"Azuro said V2 would be empty and stop on May 8 after the V3 migration window.","claim_ids":["claim:azuro:event:v3-migration"],"date_precision":"day"},{"id":"event:azuro:current-snapshot","type":"market_observation","date":"2026-08-03","description":"Current APIs reported $1.56 million of liquidity and a $147,317 positive 30-day pool result, with negative seven- and one-day windows.","claim_ids":["claim:azuro:event:current-snapshot"],"date_precision":"day"}],"sources":[{"id":"source:azuro:intro","title":"What Is Azuro?","url":"https://gem.azuro.org/knowledge-hub/introduction/what-is-azuro","publisher":"Azuro DAO","published_at":null,"accessed_at":"2026-08-03T19:31:32Z","archive_url":null,"tier":"B","role":"primary","access_state":"reachable","checked_at":"2026-08-03T19:31:32Z","content_hash":null,"evidence_locator":"Architecture page distinguishes protocol, SDK, DAO, applications and singleton liquidity.","resolving":true},{"id":"source:azuro:lp","title":"Liquidity Providers","url":"https://gem.azuro.org/knowledge-hub/how-azuro-works/protocol-actors/liquidity-providers","publisher":"Azuro DAO","published_at":null,"accessed_at":"2026-08-03T19:31:32Z","archive_url":null,