","published_at":null,"accessed_at":"2026-08-03T19:31:32Z","archive_url":null,"tier":"B","role":"aggregator","access_state":"reachable","checked_at":"2026-08-03T19:31:32Z","content_hash":null,"evidence_locator":"API snapshot returned rolling pool profit/loss under DefiLlama fee and revenue labels.","resolving":true}],"claims":[{"id":"claim:azuro:status","field_path":"status.operating_state","assertion":"Azuro was operating at the review date.","value":"operating","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:azuro:v3","source:azuro:llama-tvl","source:azuro:llama-fees"],"evidence_locator":"Current V3 release and current protocol liquidity and pool-result observations.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:azuro:outcome","field_path":"outcome.label","assertion":"Azuro is classified operating unclassified as of 2026-08-03.","value":"operating_unclassified","as_of":"2026-08-03","confidence":"medium","kind":"inference","source_ids":["source:azuro:intro","source:azuro:v3","source:azuro:llama-tvl","source:azuro:llama-fees"],"evidence_locator":"Maintained infrastructure and measurable pool activity without retained-bettor, application or LP-return evidence.","support_direction":"supports","note":"Lifecycle classification, not a claim of profitability, solvency, legality in every market, or one exclusive cause.","review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:azuro:section:what_it_is:1","field_path":"analysis.sections.what_it_is.body","assertion":"Azuro combines protocol contracts, SDK, DAO, data providers, apps and shared LP pools.","value":"Azuro combines protocol contracts, SDK, DAO, data providers, apps and shared LP pools.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:azuro:intro","source:azuro:data","source:azuro:apps"],"evidence_locator":"Current architecture and actor documentation.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:azuro:section:what_it_is:2","field_path":"analysis.sections.what_it_is.body","assertion":"Azuro applications are separate customer and legal surfaces rather than one canonical sportsbook.","value":"Azuro applications are separate customer and legal surfaces rather than one canonical sportsbook.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:azuro:intro","source:azuro:apps","source:azuro:terms"],"evidence_locator":"Current app and interface boundaries.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:azuro:section:what_happened:1","field_path":"analysis.sections.what_happened.body","assertion":"Azuro required a V2-to-V3 migration and planned to stop V2 on 2026-05-08.","value":"Azuro required a V2-to-V3 migration and planned to stop V2 on 2026-05-08.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:azuro:v3"],"evidence_locator":"Dated V3 release notice.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:azuro:section:what_happened:2","field_path":"analysis.sections.what_happened.body","assertion":"Current tracked liquidity and pool results show activity and short-window volatility.","value":"Current tracked liquidity and pool results show activity and short-window volatility.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:azuro:llama-tvl","source:azuro:llama-fees"],"evidence_locator":"Independent current API observations.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:azuro:section:why_this_outcome:1","field_path":"analysis.sections.why_this_outcome.body","assertion":"Shared liquidity and reusable tooling reduce the startup burden for applications.","value":"Shared liquidity and reusable tooling reduce the startup burden for applications.","as_of":"2026-08-03","confidence":"medium","kind":"inference","source_ids":["source:azuro:intro","source:azuro:lp"],"evidence_locator":"Current architecture and LP design.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:azuro:section:why_this_outcome:2","field_path":"analysis.sections.why_this_outcome.body","assertion":"Current evidence does not establish retained demand, app concentration or risk-adjusted LP returns.","value":"Current evidence does not establish retained demand, app concentration or risk-adjusted LP returns.","as_of":"2026-08-03","confidence":"high","kind":"unknown","source_ids":["source:azuro:llama-tvl","source:azuro:llama-fees","source:azuro:lp"],"evidence_locator":"Independent aggregates and LP risk disclosure.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:azuro:section:strategic_choices:1","field_path":"analysis.sections.strategic_choices.body","assertion":"Infrastructure, singleton pools, multi-chain deployments and delegated data provision are documented choices.","value":"Infrastructure, singleton pools, multi-chain deployments and delegated data provision are documented choices.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:azuro:intro","source:azuro:lp","source:azuro:data"],"evidence_locator":"Current protocol design.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:azuro:section:strategic_choices:2","field_path":"analysis.sections.strategic_choices.body","assertion":"pAZUR adds a two-year lock and conditional USDT distributions.","value":"pAZUR adds a two-year lock and conditional USDT distributions.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:azuro:pazur"],"evidence_locator":"Current pAZUR mechanics.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:azuro:section:operating_model:1","field_path":"analysis.sections.operating_model.body","assertion":"Apps route users to shared vAMM pools while data providers manage conditions and initial resolution.","value":"Apps route users to shared vAMM pools while data providers manage conditions and initial resolution.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:azuro:intro","source:azuro:data","source:azuro:apps"],"evidence_locator":"Current actor and condition workflow.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:azuro:section:operating_model:2","field_path":"analysis.sections.operating_model.body","assertion":"LP positions bear broad market exposure and can show negative returns.","value":"LP positions bear broad market exposure and can show negative returns.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:azuro:lp","source:azuro:llama-fees"],"evidence_locator":"LP risk disclosure and current pool-result data.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:azuro:section:token_and_value_capture:1","field_path":"analysis.sections.token_and_value_capture.body","assertion":"AZUR has a documented one-billion supply and allocation/vesting design.","value":"AZUR has a documented one-billion supply and allocation/vesting design.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:azuro:tokenomics"],"evidence_locator":"Current tokenomics page.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:azuro:section:token_and_value_capture:2","field_path":"analysis.sections.token_and_value_capture.body","assertion":"Only the two-year pAZUR path is described as eligible for variable USDT distributions.","value":"Only the two-year pAZUR path is described as eligible for variable USDT distributions.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:azuro:pazur"],"evidence_locator":"Current pAZUR rights and limits.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:azuro:section:counterfactual:1","field_path":"analysis.sections.counterfactual.body","assertion":"A canonical app and isolated liquidity would simplify attribution but weaken shared distribution and capital reuse.","value":"A canonical app and isolated liquidity would simplify attribution but weaken shared distribution and capital reuse.","as_of":"2026-08-03","confidence":"medium","kind":"inference","source_ids":["source:azuro:intro","source:azuro:apps","source:azuro:lp"],"evidence_locator":"Observed design used to bound alternatives.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:azuro:section:counterfactual:2","field_path":"analysis.sections.counterfactual.body","assertion":"Alternative token locks or orderbooks have no measured outcome in this evidence set.","value":"Alternative token locks or orderbooks have no measured outcome in this evidence set.","as_of":"2026-08-03","confidence":"high","kind":"unknown","source_ids":["source:azuro:pazur","source:azuro:intro"],"evidence_locator":"Current mechanism and evidence gap.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:azuro:section:risks_and_unknowns:1","field_path":"analysis.sections.risks_and_unknowns.body","assertion":"LP, data-provider, dispute and version-migration dependencies are material operating risks.","value":"LP, data-provider, dispute and version-migration dependencies are material operating risks.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:azuro:lp","source:azuro:data","source:azuro:v3"],"evidence_locator":"Current risk and migration evidence.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:azuro:section:risks_and_unknowns:2","field_path":"analysis.sections.risks_and_unknowns.body","assertion":"Protocol terms do not provide a gaming licence for applications or prove legal access.","value":"Protocol terms do not provide a gaming licence for applications or prove legal access.","as_of":"2026-08-03","confidence":"high","kind":"unknown","source_ids":["source:azuro:terms","source:azuro:apps","source:azuro:privacy"],"evidence_locator":"Current legal and entity boundaries.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:azuro:section:lifecycle:1","field_path":"analysis.sections.lifecycle.body","assertion":"Versioned releases and the V3 migration show active protocol maintenance.","value":"Versioned releases and the V3 migration show active protocol maintenance.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:azuro:v3","source:azuro:intro"],"evidence_locator":"Current release and architecture evidence.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:azuro:section:lifecycle:2","field_path":"analysis.sections.lifecycle.body","assertion":"Current liquidity and pool results do not resolve commercial success across applications.","value":"Current liquidity and pool results do not resolve commercial success across applications.","as_of":"2026-08-03","confidence":"medium","kind":"inference","source_ids":["source:azuro:llama-tvl","source:azuro:llama-fees"],"evidence_locator":"Independent aggregates and attribution limits.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:azuro:section:outlook_and_watch:1","field_path":"analysis.sections.outlook_and_watch.body","assertion":"Current activity supports continued operation but not an application-level growth forecast.","value":"Current activity supports continued operation but not an application-level growth forecast.","as_of":"2026-08-03","confidence":"medium","kind":"inference","source_ids":["source:azuro:v3","source:azuro:llama-tvl","source:azuro:llama-fees"],"evidence_locator":"Current release and pool observations.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:azuro:section:outlook_and_watch:2","field_path":"analysis.sections.outlook_and_watch.body","assertion":"Application retention, LP returns, data concentration and pAZUR distributions are decisive missing signals.","value":"Application retention, LP returns, data concentration and pAZUR distributions are decisive missing signals.","as_of":"2026-08-03","confidence":"high","kind":"unknown","source_ids":["source:azuro:apps","source:azuro:lp","source:azuro:data","source:azuro:pazur"],"evidence_locator":"Current architecture and token design.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:azuro:metric:liquidity","field_path":"metrics[metric:azuro:liquidity:2026-08-03T18:13:23Z].value","assertion":"Tracked protocol liquidity was 1563088 USD for the stated scope and window.","value":1563088,"as_of":"2026-08-03T18:13:23Z","confidence":"high","kind":"fact","source_ids":["source:azuro:llama-tvl"],"evidence_locator":"Provider response retrieved and frozen in the research artifact.","support_direction":"supports","note":"Limits: pool_liquidity_not_wagers, not_users, not_operator_solvency.","review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:azuro:metric:pool-result-24h","field_path":"metrics[metric:azuro:pool-result-24h:2026-08-03T19:31:32Z].v